package com.example.starter.orchestrator;

/**
 * 请求参数非法（计划结构错误，如引用了不存在的节点），映射 HTTP 400。
 */
public class InvalidPlanException extends RuntimeException {
    public InvalidPlanException(String message) {
        super(message);
    }
}

package com.example.starter.orchestrator;

/**
 * 计划存在显式或条件引用导致的循环依赖，映射 HTTP 422。
 * 消息中携带完整依赖路径。
 */
public class CyclicDependencyException extends RuntimeException {
    public CyclicDependencyException(String message) {
        super(message);
    }
}

package com.example.starter.orchestrator;

/**
 * 同一 requestId 以不同参数重复提交，映射 HTTP 409。
 */
public class IdempotencyConflictException extends RuntimeException {
    public IdempotencyConflictException(String message) {
        super(message);
    }
}

package com.example.starter.orchestrator;

/**
 * 计划或节点不存在，映射 HTTP 404。
 */
public class NotFoundException extends RuntimeException {
    public NotFoundException(String message) {
        super(message);
    }
}

