    }

    @Test
    void topologicalSortPutsPrerequisitesFirst() {
        Map<String, List<String>> graph = Map.of(
                "ui", List.of("service"),
                "service", List.of("db"),
                "db", List.of()
        );
        assertThat(DagCycleDetector.topologicalSort(graph)).containsExactly("db", "service", "ui");
