package com.example.starter.orchestrator;

import com.example.starter.orchestrator.repo.OrchestratorRepository;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.BeforeEach;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.boot.test.context.TestConfiguration;
import org.springframework.context.annotation.Bean;
import org.springframework.context.annotation.Primary;

import java.time.Clock;
import java.time.Instant;
import java.time.ZoneId;
import java.util.concurrent.Executor;

/**
 * 编排器 H2（MODE=MySQL）集成测试基类：同步执行器保证断言确定性，
 * 固定时钟保证时间可控；每个场景前清空数据避免顺序依赖。
 */
@SpringBootTest(properties = "spring.task.execution.mode=none")
abstract class AbstractOrchestratorH2Test {

    @Autowired
    protected OrchestratorRepository repo;

    @Autowired
    protected com.example.starter.orchestrator.service.LaunchPlanService service;

    @Autowired
    protected ObjectMapper objectMapper;

    @BeforeEach
    void cleanData() {
        repo.deleteAllData();
    }

    /**
     * 用同步执行器替换异步线程池：提交即在调用线程内把计划执行到终态。
     */
    @TestConfiguration
    static class SyncExecutorConfig {
        @Bean(name = "planExecutor")
        @Primary
        Executor syncPlanExecutor() {
            return Runnable::run;
        }

        @Bean
        @Primary
        Clock fixedClock() {
            return Clock.fixed(Instant.parse("2026-09-22T08:00:00Z"), ZoneId.of("UTC"));
        }
    }
}

